use sakila;
-- List the number of films per category.
SELECT 
    COUNT(film_id), name AS category_name
FROM
    film_category AS f
        JOIN
    category AS c ON f.category_id = c.category_id
GROUP BY category_name;
-- Retrieve the store ID, city, and country for each store.
SELECT 
    store_id, city, country
FROM
    store AS s
        JOIN
    address AS a ON s.address_id = a.address_id
        JOIN
    city AS c ON c.city_id = a.city_id
        JOIN
    country AS co ON co.country_id = c.country_id;
    -- Calculate the total revenue generated by each store in dollars
    select store_id ,sum(amount) as total_revenue from staff as s left join payment as p on s.staff_id = p.staff_id group by store_id;
    -- Determine the average running time of films for each category.
    SELECT 
    name AS category_name, AVG(length) AS avg_running_time
FROM
    film f
        JOIN
    film_category AS c ON f.film_id = c.film_id
        JOIN
    category AS ca ON ca.category_id = c.category_id
GROUP BY category_name;
    -- Bonus 
    -- 5.Identify the film categories with the longest average running time.
    
    -- 6.Display the top 10 most frequently rented movies in descending order.
    select f.film_id ,title,count(rental_id) as most_frequently_rented from film as f join inventory as i on f.film_id = i.film_id join rental as r on r.inventory_id =i.inventory_id group by film_id order by most_frequently_rented desc limit 10;
    
    -- 7. Determine if "Academy Dinosaur" can be rented from Store 1.
    select s.store_id from film as f join inventory as i on f.film_id = i.film_id join store as s on s.store_id = i.store_id where title = "Academy Dinosaur"and i.store_id=1 ;
    -- 8.Provide a list of all distinct film titles, along with their availability status in the inventory. 
    -- Include a column indicating whether each title is 'Available' or 'NOT available.'
    -- Note that there are 42 titles that are not in the inventory, and this information can be obtained using a CASE statement combined with IFNULL."
    select distinct f.title ,
    case
        when i.inventory_id is null then "Not available"
        else 'available'
        end as availability 
    from film as f left join inventory as i on f.film_id=i.film_id;
